    "creativeSample": "纸箱一个个封好，房间渐渐空了。五年了，这个小房间见证了我的成长：第一份工作的兴奋、失恋的痛苦、深夜加班的疲惫、周末独处的安宁。墙上还有当年贴的便利贴，上面写着：'加油，你可以的！'字迹已经褪色，但我还记得写下这句话时的心情。窗外的梧桐树叶子又绿了，而我却要走了。也许多年以后，我会想起这个小房间，想起那个在这里哭过笑过的自己。再见了，我的青春。我抱着最后一个纸箱走出门，回头看了一眼空荡荡的房间。阳光从窗口斜斜地照进来，落在地板上，像是在和我轻声告别。我轻轻地关上门，没有回头。",
