    "creativeSample": "雨一直下，没有停的意思。我坐在窗边，捧着热茶，看着雨水顺着玻璃流下。这样的日子适合什么都不做，就这样静静地待着。我想起很多事：小时候最喜欢下雨天，可以不用出门玩；长大后讨厌下雨，因为上班不方便；现在又开始喜欢了，因为它给了我一个理由，可以名正言顺地独处。雨声很催眠，我渐渐放空了思绪。也许人生就是这样，在不同的阶段，对同一件事有不同的感受。我把窗户推开一条缝，让雨丝的湿气和泥土的味道一起钻进屋子里。茶已经凉了，我却舍不得换一杯。雨声一直在耳边，像一位不急不躁的老朋友。",
