    "creative": "描写一个人在寒冷的冬夜独自走在街上，看到便利店的暖光的瞬间。",
    "creativeSample": "风很大，冷得刺骨。我缩着脖子快步走着，双手插在口袋里，呼出的气在空中形成白雾。街上人很少，路灯把影子拉得很长。突然，前方出现了便利店的灯光，明亮而温暖。我推门进去，暖气扑面而来。店员说了声'欢迎光临'，我点点头，在货架间慢慢走着。也许我并不需要买什么，只是想在这温暖的地方多待一会儿。最后我买了一杯热咖啡，握在手里，感受着那份温度。我把围巾往上拉了拉，把整个脸都埋了进去，只露出一双眼睛。前方的便利店像是冬夜里的一座灯塔，我心里想着，今天终于可以在那里停下来歇一歇。",
