    "creativeSample": "“这票有问题。”安保拿着扫描仪，指着屏幕上的红色警告。\n“不可能，我是从官网——”\n“二维码是伪造的。”他打断你，开始叫其他同事，“你得出去，我们要报警。”\n你的心脏狂跳。这是你等了半年的演唱会，是你存了三个月钱买的票——即使是假的，你也不能就这样离开。\n“等等。”你看着他的工作证，上面夹着一张照片，是个大概五六岁的小女孩，笑得很灿烂。你赌了一把：“你女儿？”\n他愣了一下，警惕地看着你：“关你什么事？”\n“我是儿科医生。”你掏出自己的工作证，“如果你让我进去，我可以帮你女儿——比如说，如果她有什么健康问题，我可以免费咨询，甚至帮你预约专家号。”\n他的表情变了，从警惕到犹豫：”你在贿赂我？”\n“我在交换。”你压低声音，“你知道儿科专家号有多难挂，你也知道我只是想看演唱会，我不是黄牛，我不是罪犯，我只是买错了票。”\n他盯着你，沉默了很久。后面排队的人开始抱怨，音乐已经开始了，你能听见里面传来的鼓点。\n“她有哮喘。”他最终说，“药很贵，而且经常发作，我们去了三家医院都说要等。”\n“我可以帮你。”你说，手心全是汗，“我认识呼吸科主任，我可以让你下周就带她去看。”\n他看着你，又看了看身后的队伍，最后说：”进去吧。快点，别让别人看见。”\n你几乎是跑进去的，心跳快得像要爆炸。音乐声淹没了一切，你挤进人群，但脑子里全是刚才的对话。\n<strong>你刚才做了什么？你用职业身份做了交易，你贿赂了安保，你——</strong>\n演唱会结束后，你走出场馆，看见那个安保还在门口。他叫住你，递过来一张纸条，上面是他女儿的名字和电话。\n“你说话算数吗？”他问。\n你点头，接过纸条。\n回家路上，你一直捏着那张纸，想着明天要怎么跟呼吸科主任开口，想着如果主任问你“这是什么关系的孩子”，你要怎么解释。\n但更让你不安的是，你现在欠了一个陌生人一个人情，而他知道你的脸，知道你是医生，知道你会为了一张演唱会门票突破职业底线。\n<strong>如果下次他又找你，要求更多呢？</strong>\n你把纸条存进了钱包，但整晚没睡，盯着天花板，想着那场演唱会是否真的值得。",
