    "creative": "写一个权力关系的颠覆：你抓住了上司的把柄(比如财务造假的证据)，但不是为了举报，而是为了要挟他给你升职机会，谈判在他的办公室进行。",
    "creativeSample": "“我想我们需要谈谈。”你说，关上了办公室的门。\n上司抬头，表情警惕：”什么事？”\n你把U盘放在桌上，推向他。“去年Q3的财务报表，真实版本。”\n他的脸色瞬间变了，从困惑到震惊，再到一种压抑的愤怒。“你从哪——”\n“我怎么拿到的不重要。”你打断他，“重要的是，这些数据如果被审计看到，你知道会发生什么。”\n办公室里的空调很响，但你们之间的沉默更响。他盯着那个U盘，手指在桌面上轻轻敲击，像在计算什么。\n“你想要什么？”他最终问，声音很轻。\n“部门主管的位置。”你说，“下个月的晋升名单，我要在上面。”\n他笑了，那种笑容里有嘲讽，也有一种奇怪的欣赏：”你知道你在做什么吗？这是敲诈。”\n“我知道。”你的声音比预期中更稳，“但你也知道，如果我真的想举报，我早就去找审计了。我只是想要一个公平的机会。”\n“公平？”他重复这个词，像在咀嚼什么苦涩的东西，“你用偷来的证据要挟我，然后跟我谈公平？”\n你没有回答，只是盯着他，等待。\n<strong>这是最关键的时刻——如果他拒绝，你要真的去举报吗？如果你举报了，你自己会不会也被牵连？如果他答应了，你要怎么面对那些真正靠实力升职的同事？</strong>\n“好。”他说，拿起那个U盘，“我答应你。但有一个条件。”\n“什么条件？”\n“从今天开始，你就是我的人了。”他的眼神很冷，“你想要权力，我给你。但你要记住，<strong>你现在和我绑在一起了</strong>。如果我倒了，你也完了。”你点头，但手心在出汗。\n“还有，”他站起来，走到你面前，“你以为只有你有我的把柄吗？”他从抽屉里拿出一个文件夹，扔在桌上，”你去年报销的那些'差旅费'，我都查过了。有三笔是假的，对吗？”\n你的呼吸停了一秒。\n“所以现在，”他笑了，“我们是平等的。你有我的把柄，我有你的。谁都别想出卖谁。”\n你拿着那个文件夹走出办公室，里面是你去年所有的报销记录，有几页被红笔标注了。你确实虚报过几次，只是小额的，你以为没人会查。\n<strong>但现在你意识到：你本来想控制他，但他早就准备好了反制手段。你们不是上下级，而是共犯。</strong>\n一个月后你升职了，在庆功宴上，上司当众祝贺你，所有同事都在鼓掌。但只有你们两个知道，那个掌声下面，埋着什么。",
    "erotica": "写一个情人节后的补偿性爱：错过节日的情侣，在家中的激烈弥补。",
    "eroticaSample": "错过的节日成了此刻疯狂的导火索。他刚进家门就将我抵在玄关墙上，大手粗鲁地撕烂了我的内衣。这是一种带有补偿性质的泄欲，他掏出那根狰狞、布满青筋的昂扬，没有任何前戏便扎进了我那泛滥的穴口。\n这种生硬的摩擦感迅速转化为剧烈的火辣快感，他在走廊里加速了抽送，每一次重插都让我感到内脏在震动。随后我们跌落在客厅地板上，他让我撅起屁股，从后方猛地刺入最深处。他大手死死掐住我的腰窝，在那片红肿的私处带起大片黏滑的淫液。他在这种近乎疯狂的补救中不停捣弄，直到他在最后一次深插中将精液狠狠灌入，烫得我全身抽搐。"
