    "creative": "写一个荒诞场景中的原始冲动：在朋友孩子的生日派对上，你去储藏室拿东西，碰到了那个穿着卡通玩偶服装的表演者，他正在脱头套休息。你们在狭小、荒诞的空间里，短暂地对视，然后发生了一场完全不合时宜的、由荒诞感催化的情绪爆发(可以是争吵、大笑、或情绪崩溃)。",
    "creativeSample": "储藏室的门没锁，你推开时，看见一只巨大的粉红兔子坐在地上，头套放在旁边。\n是个男人，大概三十出头，满头大汗，正在喝水。\n“抱歉，我——”你准备退出去。\n“别走。”他说，声音很疲惫，“帮我拿下后面的拉链，我卡住了。”\n你犹豫了一下，走过去，帮他拉开卡通服背后的拉链。布料很厚，里面全是汗味。\n“谢了。”他脱下上半身的服装，露出湿透的T恤，“这工作真他妈的荒诞。”\n你笑了：”但小孩子很开心。”\n“小孩子开心。”他重复，然后突然笑了，笑得很大声，“对，小孩子开心，所以我要在四十度的天气里穿着这身皮套跳舞，<strong>假装自己是只兔子</strong>。”\n他的笑声在狭小的储藏室里回荡，有点歇斯底里。\n“你还好吗？”你问。\n“不好。”他说，笑容消失了，“我他妈的博士毕业，现在在扮兔子。我今天早上刚收到论文被拒的邮件，然后我穿上这身衣服，去给一个五岁小孩唱生日快乐。”\n你不知道该说什么，只是站在那里，看着他。\n“你呢？”他突然问，“你为什么躲进来？”\n“我没有躲——”\n“别装了。”他打断你，“这是储藏室，正常人不会主动进来。你在逃避什么？”\n你沉默了，然后说：“外面那些人，都在问我什么时候结婚，什么时候生孩子。”\n“所以你躲进来了。”\n“对。”\n你们对视了几秒，然后同时笑了。<strong>不是礼貌的笑，而是那种无奈的、自嘲的、带着绝望的笑。</strong>\n“我们真可悲。”他说。\n“是啊。”你说。\n外面传来小孩的尖叫声，有人在喊“兔子兔子”，他叹了口气，拿起头套，准备戴上。\n“等一下。”你说，“你就这样回去？你不想……我不知道，做点什么？”\n“做什么？”\n“我不知道。”你说，“但我觉得，如果你现在就戴上头套回去，<strong>你会恨自己一辈子</strong>。”\n他盯着你，然后把头套扔在地上，用力踩了一脚。\n“操。”他说。\n“操。”你重复。\n你们站在储藏室里，听着外面的欢笑声，感受着那种<strong>完全的、彻底的、荒诞的不合时宜</strong>。\n十分钟后，他还是戴上了头套，走了出去。\n但你们都知道，<strong>那十分钟，是你们今天唯一真实的时刻</strong>。",
    "erotica": "写一个春节独自在家的自慰场景：用视频里的情色内容满足自己，释放孤独。",
    "eroticaSample": "春节的家里格外安静，我独自窝在床上，打开平板播放早已存好的情色视频。屏幕上缠绵的身影让我下体迅速发热。我脱去睡衣，双腿大开，房间只剩视频里压抑的喘息与我的心跳。我拿起跳蛋，先贴上阴蒂，视频里女人的呻吟与跳蛋的震颤同步响起，我立刻腰肢轻颤，蜜汁如潮涌出。我又取出双头假阳具，一端缓缓推入阴道，另一端对准后庭，慢慢全部没入。那种被彻底填满的饱胀感让我发出满足的低吟，随着视频节奏前后抽动，内壁每一处褶皱都被摩擦得发烫。我一只手揉捏乳房，指尖狠捏乳头，另一手加快假阳具的进出速度。视频里的三人场景让我幻想自己也在其中，孤独瞬间被欲望填满。高潮来临时，我盯着屏幕，身体弓成满月，阴道和后庭同时剧烈收缩，喷出晶莹液体，床单湿了一大片。我没有关视频，继续用玩具延长快感，一次次攀上高峰，直到全身瘫软，汗水浸透头发。视频还在播放，我却在余韵中微笑——春节的孤独，被我用最彻底、最自我的方式温柔拥抱并释放，身体虽一人，心却在快感中找到最完整的满足。"
