    "creative": "写一个公开的羞耻：你在社交媒体上误发了一张背景中出现敏感物品的照片(比如书架上的私密书籍、桌上的药瓶等)，被朋友截图转发调侃。你可以删帖，但截图已经扩散，你必须决定是解释、沉默，还是干脆“破罐破摔”地公开承认。",
    "creativeSample": "照片发出去五分钟后，你才注意到。\n那是一张你在家办公的照片，本来是想晒新买的咖啡杯，但<strong>背景的书架上，清晰地摆着一本封面很露骨的书，标题一目了然</strong>。\n你的心脏停了一拍，立刻删帖。\n但已经晚了。\n手机开始疯狂震动，都是私信：\n<strong>“哈哈哈哈你看什么书啊？”</strong>\n<strong>“姐妹你背景……”</strong>\n<strong>“截图了，不用谢。”</strong>\n你打开群聊，有人已经把截图发出来了，配文：<strong>“今日份快乐来源。”</strong>\n下面一堆人在笑，在调侃，<strong>没有恶意，但每一句话都像针一样扎在你身上</strong>。\n你盯着屏幕，手指悬在键盘上，<strong>不知道该解释、道歉，还是假装没看见</strong>。\n解释？怎么解释？说“那不是我的书”？但它确实在你家书架上。\n道歉？为什么要道歉？<strong>看什么书是你的自由，你又没有伤害任何人。</strong>\n假装没看见？但截图还在传播，明天公司的人可能都会看到。\n你深吸一口气，在群里发了一条消息：\n<strong>“对，我看这种书，有问题吗？”</strong>\n群聊瞬间安静了。\n十秒后，有人发了个尴尬的表情。\n又有人说：<strong>“没问题啊，只是没想到你……”</strong>\n“没想到我什么？”你继续打字，“没想到我也是个正常人？也有欲望？也会好奇？”\n<strong>你本来只是想堵住他们的嘴，但打着打着，你发现自己是真的生气了。</strong>\n“你们平时看爽剧、看小黄文、刷短视频，没人觉得有问题，<strong>为什么我看本书就要被截图传播？</strong>”\n没人回复了。\n你退出群聊，关掉手机，坐在沙发上，盯着那本书。\n<strong>你突然意识到，你刚才做的事，可能比误发照片更严重</strong>——你在一群认识的人面前，主动承认了自己的“不体面”。\n第二天上班，有人用奇怪的眼神看你，<strong>但没人敢当面提</strong>。\n你的好朋友私下问你：“昨晚你是不是喝多了？要不要我帮你在群里解释一下？”\n“不用。”你说，“我说的都是真话。”\n“但你这样……”她犹豫了一下，“你不怕别人怎么看你吗？”\n<strong>“我怕。”</strong>你说，<strong>“但我更怕假装那本书不是我的，假装我没看过，假装我是个'干净'的人。”</strong>\n<strong>“因为如果我假装，那就意味着我承认了——看这种书是羞耻的。”</strong>\n她没说话。\n一周后，有人在群里发了张照片，背景里有个明显的情趣用品。<strong>这次没人截图，没人调侃，都假装没看见。</strong>\n<strong>你不知道这是因为大家学会了尊重隐私，还是因为你上次的“破罐破摔”让他们意识到，有些玩笑不能开。</strong>\n但你知道，<strong>那张截图还在某些人的手机里，可能会永远存在</strong>。\n<strong>而你已经不在乎了</strong>。",
    "erotica": "写一个化装舞会上：面具后的三个陌生人在密室中的一夜。",
    "eroticaSample": "密室烛光摇曳，三人面具遮脸。她跪在中间，双眼迷离。先含住第一个男人那根紫胀、跳动的肉柱，舌尖绕龟头打圈，喉咙深处感受着那份饱满。第二个男人从后面贴上来，大手揉捏着她的乳房，手指探进她湿热的甬道快速抽插。\n随后第一个男人从正面进入，她腿缠上他腰，感受着那根巨物劈开内里的褶皱。第二个男人则移向后庭，阴茎抵住褶皱，暴力推进。她被两根巨大的肉棒前后夹击，身体在剧烈的撞击中扭动，呻吟被面具闷住。两人节奏同步，每一下都直击最深处。高潮时她尖叫着缩紧，两人先后在她体内释放，滚烫的热流填满了她的每一寸缝隙。"
