    "creative": "写一个身体的陌生化：一觉醒来，你发现自己的身体发生了某种无法解释的变化(比如突然多了一个器官的感知、失去了某种感觉、或镜子里的自己和记忆不符)。你试图求助，但没人相信你，医生说“一切正常”。",
    "creativeSample": "你是在刷牙时发现的。\n舌头碰到口腔上颚，<strong>那里有个东西</strong>。\n不是溃疡，不是食物残渣，而是<strong>一颗小小的、硬硬的凸起</strong>，像是……<strong>牙齿</strong>。\n你吐掉牙膏，张大嘴对着镜子看——<strong>上颚正中央，确实有一颗小小的、尖锐的牙齿，正在往外长</strong>。\n你的手开始发抖。\n<strong>人的上颚不长牙齿，这不可能，这不符合人体结构。</strong>\n你用手指摸那颗牙，它很真实，很坚硬，<strong>当你按压时，还有轻微的疼痛</strong>。\n你立刻去了医院，挂了急诊。\n医生让你张嘴，看了三秒，说：“没什么问题啊。”\n“上颚，那里。”你指着，“有颗牙齿。”\n医生又看了一遍，皱眉：“我没看见牙齿，你是不是太紧张了？”\n“不可能，我明明——”你掏出手机，打开手电筒，对着镜头张嘴拍照。\n照片里，<strong>上颚光滑，什么都没有</strong>。\n你愣住了。\n“你看。”医生把照片放大给你看，“什么都没有，可能是你最近压力太大，产生了幻觉。”\n“但我能摸到！”你说，当场把手指伸进嘴里，按在那个位置——<strong>牙齿还在，尖锐、真实</strong>。\n医生盯着你的动作，表情变得警惕：“你现在摸到了什么？”\n“牙齿，就在这里。”\n“但那里什么都没有。”医生说，“我建议你去看看心理科。”\n你走出医院，坐在路边，<strong>反复用舌头舔那颗牙，确认它的存在</strong>。\n<strong>它在，它确实在，但为什么只有你能感觉到？</strong>\n回家后，你试图用手机拍视频，<strong>但屏幕里的你，上颚永远是光滑的</strong>。\n你试图让朋友帮你看，她张望了半天，说：“你神经过敏了吧？那里什么都没有。”\n<strong>只有你，只有你一个人，能感觉到那颗牙。</strong>\n接下来的一周，<strong>那颗牙越长越大</strong>。\n从一个小凸起，变成一颗完整的尖牙，<strong>开始影响你说话，开始在你吃东西时刮到舌头，开始让你每时每刻都意识到它的存在</strong>。\n但镜子里，照片里，别人的眼里，<strong>它不存在</strong>。\n你开始怀疑自己是不是疯了，<strong>是不是这颗牙从一开始就是幻觉，是不是你的大脑出了问题</strong>。\n但<strong>幻觉会流血吗？</strong>\n你用力按那颗牙，它刺破了你的手指，血流出来，<strong>很真实，很疼</strong>。\n你盯着那滴血，突然笑了。\n<strong>“至少我知道我没疯。”</strong>你对镜子里的自己说。\n镜子里的你也在笑，<strong>但嘴里什么都没有，只有一排正常的牙齿</strong>。\n<strong>而你舌头上的刺痛感，正在提醒你：那颗牙还在，而且还在长</strong>。",
    "erotica": "写一个尝试新体位的性爱：侧卧式，缓慢而深入的亲密连接。",
    "eroticaSample": "我们像两片紧紧叠在一起的贝壳，侧躺在被褥间。他从后方贴上来，一条腿挤进我双腿之间，将我的臀瓣向两侧拨开。由于重力的作用，我那早已湿透的小穴在空气中微微翕张，等待着侵入。他并不急于冲刺，而是扶着那根紫红发烫的巨物，缓慢而坚定地一寸寸没入。这种体位让那根粗长的肉棒能完全贴合我的曲线，每一次深入的顶弄都直接碾过我的宫颈口。我发出一声满足的低吟，感受着那层层褶皱被撑平的饱涨感。他在我耳边低喘，动作轻缓却带着不容拒绝的厚重，每一记研磨都带起阵阵酸麻的电流。我们在这种静谧的亲密中，感受着肉柱在体内每一毫米的推进，直到他在最深处的一次重击中，将滚烫的白浊尽数灌满我的甬道。"
