    "creative": "写一个终极筛选：你赢得了一张双人旅行机票，但你目前单身。于是你发起了一场“最终试睡”——邀请几个潜在对象，用一晚的时间测试彼此的契合度，最契合的人将成为你的旅伴(和可能的伴侣)。",
    "creativeSample": "<strong>规则很简单：一晚上，一张床，看谁能和你睡得最舒服</strong>。\n不是性，<strong>是真正的“睡觉”</strong>——看谁的呼吸节奏和你匹配，看谁的体温让你觉得安心，看谁翻身时不会吵醒你，<strong>看谁能让你在第二天早上，不想离开那张床</strong>。\n你在约会软件上发了这个“招募”，<strong>本以为没人会理，结果收到了十几个报名</strong>。\n你筛选了三个： \n<strong>A，程序员，说话很少，但回复消息很及时</strong>。\n<strong>B，健身教练，照片里笑得很阳光</strong>。\n<strong>C，作家，简介里写着“我擅长倾听”</strong>。\n<strong>第一晚，是A</strong>。\n他准时到达，带了自己的枕头，说“我有颈椎病，只能用这个”。\n你们躺下，<strong>他真的一句话都不说，背对着你，很快就睡着了</strong>。\n<strong>你盯着他的背影，觉得很安全，但也很孤独</strong>。\n<strong>早上醒来，他已经走了，床头留了张便条：“谢谢，但我觉得我们不合适。”</strong>\n<strong>第二晚，是B</strong>。\n他很热情，进门就夸你的房间“很温馨”，<strong>然后开始讲他的健身故事，讲了一个小时</strong>。\n你们躺下，<strong>他的手臂很自然地搭在你腰上，力度刚好，不会让你觉得被束缚</strong>。\n<strong>但他打呼噜，很大声，你一整晚没睡着</strong>。\n<strong>早上你委婉地说“可能不太合适”，他笑着说“我懂”，然后离开了</strong>。\n<strong>第三晚，是C</strong>。\n他到的时候下着雨，浑身湿透了，你递给他毛巾，他说“谢谢，你真体贴”。\n你们聊了很久，<strong>从彼此的童年聊到对未来的期待，从喜欢的书聊到害怕的事</strong>。\n躺下时已经凌晨两点，<strong>他没有碰你，只是侧身看着你，轻声问：“你紧张吗？”</strong>\n“有一点。”你说。\n“我也是。”<strong>他笑了，然后闭上眼睛，“晚安。”</strong>\n<strong>你盯着他的睡脸，突然觉得很平静</strong>。\n<strong>他的呼吸很轻，和你的节奏慢慢同步，他的体温温暖但不炙热，他翻身时会下意识避开你</strong>。\n<strong>你睡得很好，多年来最好的一次</strong>。\n<strong>早上醒来，他还在，正在厨房给你煮咖啡</strong>。\n“怎么样？”他问，“我通过测试了吗？” \n你点头，<strong>但心里有个声音在说：这不是测试，这是你第一次和一个人睡在一起，感觉像回家</strong>。\n<strong>“那我们什么时候出发？”</strong>他问，眼睛里有期待，也有一点紧张。\n“下个月。”你说，<strong>“但在那之前，你能不能……再来睡几晚？”</strong>\n<strong>他笑了：“你是想确认我不是碰巧那天表现好？”</strong>\n“不是。”你说，<strong>“是我想确认，每天早上醒来，我都还想看见你。”</strong>\n<strong>他没说话，只是走过来，抱住你，把头靠在你肩上</strong>。\n<strong>你闭上眼睛，闻到他头发上的洗发水味道，突然意识到：</strong>\n<strong>这不是一场测试，这是一场赌博</strong>。\n<strong>你赌这个能和你睡得舒服的人，也是那个能陪你走很远的人</strong>。\n<strong>而现在，你好像赌赢了</strong>。",
    "erotica": "写一个在镜子前的性爱场景：视觉刺激与自我观察的双重快感。",
    "eroticaSample": "我被他从身后横抱起，重重抵在冰冷的全身镜前。我双手死死撑在镜面上，五指因用力而指节泛白，镜子里清晰地映出我此时那副贪婪且淫靡的模样。我主动分.开双.腿，通过镜子观察自己那早已红肿、湿淋淋的阴唇。\n他粗大的手指从后方伸入，精准地按压住我那颗剧烈跳动的阴蒂，反复揉搓拨弄，我看着镜子里的自己因这种直观的刺.激而挺起胸脯，乳房在空气中剧烈晃荡，乳尖在镜面的倒映下红得发紫。他掏出那根狰狞挺立的肉棒，抵在我的穴口反复磨蹭，带起大片晶莹的蜜汁，将镜面也熏出了一层薄薄的雾气。\n“看着它怎么吃进去的。”他在我耳边低吼。\n我瞪大眼睛，在镜子的注视下，看那根紫红色的巨.物一寸寸撑开我鲜红的肉褶，彻底没入我的阴道深处。镜子里那种视觉上的被填满感，让我的阴道壁产生了一阵阵疯狂的痉挛。我主动后仰，迎合他每一次深重而粗野的抽插，看着我们交合的部位带起黏滑的白色沫儿。\n这种暴露在自己目光下的罪恶感瞬间点燃了生理顶峰。我尖叫着，在镜子里看到自己因高潮而失神的双眸。他发出一声闷哼，将滚烫的精液尽数射进我那剧烈收缩的子宫口，部分浓稠的白浊顺着我颤抖的大腿根部，滴滴答答地落在地毯上，也在镜面留下了几点浑浊的痕迹。我们两人汗湿的肉体在镜中交缠，在那一刻，视觉的凌虐与肉体的欢愉达到了完美的共振。"
