    "creative": "描写生日后的第二天，带着新的一岁的感觉面对生活。",
    "creativeSample": "生日过去了，我又老了一岁。早上照镜子，好像也没什么变化，但心里知道不一样了。这一岁我要做什么？我列了个清单：学一门新技能、去一个没去过的国家、读完十本书、谈一场认真的恋爱。看着这个清单，我觉得很有动力。以前我总觉得年龄是负担，数字越大越焦虑。但现在我明白了，每一岁都是经验的积累，都是成长的证明。我不再害怕变老，反而期待着未来的每一年。出门时，我对着镜子笑了笑：新的一岁，多多指教。世界还是那个世界，但我已经不是昨天的我了。",
