    "creativeSample": "今天我一个人搬完了所有家具。不是因为没人帮忙，而是我想证明给自己看——我可以。邻居大叔看见了，说：小姑娘，这么重的东西，叫个男人来帮忙啊。我笑着说：不用，我自己可以。搬完最后一个书柜，我累得坐在地上，但心里满是成就感。以前我总觉得女生就该柔弱一点，需要被照顾。但现在我明白了，柔软不代表软弱，我可以既温柔又强大。晚上我站在镜子前，看着自己手臂上的肌肉线条，突然觉得很骄傲。这就是我，一个可以独立完成任何事的女人。",
