    "eroticaSample": "昏暗的卧室被燥热的雄性体味充斥。我大张着双腿陷在丝绒榻中，居高临下地俯瞰着这三头为我疯狂的野兽。景修整张脸埋在我的胯下，湿冷而粗糙的舌面正大面积地覆在早已充血红肿的阴蒂上，每一次精准的重压弹拨，都激起我腹股沟处难以自抑的痉挛。\n左右两侧，陆锋和凯文正赤裸着上身，他们粗砺的指甲反复揉掐着我的乳尖，甚至能听到指甲盖剐蹭过紧绷皮肉的摩擦声。当我的身体因为阴蒂的吸吮而弓起时，凯文那三根粗壮如杵的手指，带着大股溢出的温热阴道液，猛地刺入那道层层叠叠的软肉。指关节在甬道内疯狂搅动，那种内壁被撑开到极致、每一处褶皱都被强行抚平的胀满感，让我喉咙里溢出濒临破碎的浪叫。\n“把它插进来……”我揪住陆锋的短发下达指令。凯文心领神会地抽出湿淋淋的手指，带出一连串粘稠的拉丝。早已涨得发紫、青筋暴起的肉棒瞬间抵住那道还在颤抖合拢的洞口。\n陆锋扶着狰狞的冠头，借着凯文留下的粘液，腰部陡然发力，如生铁般坚硬的肉柱一贯到底。我感到宫颈口被那股蛮横的冲力撞得生疼，却又因这极致的深入而感到灵魂战栗。他每一次毫无保留的重击，都让甬道内的红肉被这粗壮的棱角反复碾压、变形。我彻底沉沦在这种由三人合力构建的肉欲地狱里，在被撑开、被填满、被膜拜的快感巅峰中，迎接意识的彻底崩塌。"
