    "creative": "描写找到真正热爱的工作后，每天充满动力的感觉。",
    "creativeSample": "以前我上班像上刑，每天都在倒数下班时间。但换了现在这份工作后，一切都不一样了。我做的是内容创作，每天都在写作、拍摄、剪辑，虽然累但很开心。早上醒来，我不再需要闹钟催，因为我期待今天的工作。同事问我：你怎么总是这么有精神？我说：因为我在做自己喜欢的事。老板夸我效率高，其实是因为我根本不觉得这是工作，更像是在玩。下班后我还会继续学习新技能，看相关的书，因为我想做得更好。<strong>当工作变成热爱，就不再是负担，而是生活的一部分。</strong>我终于明白了那句话：找到你热爱的事，你这辈子就不用工作了。",
    "erotica": "写一个工作伙伴的化学反应：出差时和同事在酒店房间里的意外。",
    "eroticaSample": "酒店套房的冷气无声地流动，我躺在另一张床上，黑暗中那阵细微、急促且粘腻的喘息声像火星点燃了氧气。那是他，平日里西装革履、冷静自持的搭档，此刻正因为压抑的自.慰而浑身颤抖。\n我没有揭穿，反而翻过身，故意让真丝睡裙擦过床单发出窸窣声。他僵住了，呼吸频率紊乱得厉害。我盯着黑暗中那个模糊的轮廓，声音沙哑且直白：“既然已经湿了，为什么不继续？”\n沉默在空气中炸裂。几秒后，床垫塌陷，他带着满身的皂香和浓烈的雄性热度覆了上来。他粗糙的手掌直接探入我的裙摆，指腹精准地揉捏着那处早已泥泞的缝隙。\n“我也想。”我张开腿，主动勾住他的腰，感受他那根已经肿胀到发烫的肉棒隔着内裤蛮横地顶在我的阴蒂上。\n没有多余的温存，他单手扯掉阻碍，当那根狰狞的硬物撑开紧致的阴道口，蛮横地贯穿到底时，我清晰地感受到了阴道壁被生生撕开、撑平的褶皱感。那是种近乎暴力的饱胀，我发出一声支离破碎的呻吟，手指死死扣进他背部紧绷的肌肉里。\n他在我体内剧烈地抽动，每一次进出都带出粘稠的汁液，肉体撞击出的“啪啪”声在寂静的房间里震耳欲聋。我主动扭动腰肢，配合着他进攻的角度，疯狂地吮吸着那处滚烫。我们像是在进行一场最原始的合同谈判，每一寸肌肤的摩擦都是利益的交换，每一声失控的喘息都是绝对的合意。\n当高潮如海啸般将我们淹没时，他低吼着狠狠顶入最深处，滚烫的精液溅射在阴道深处的触感让我的内壁发生了痉挛性的绞杀。我们在这场意外的博弈中彻底缴械，黑暗中只有交叠的体温和从未如此默契的残余激情。"
