    "creative": "描写面对突发状况时，选择积极应对而非抱怨的态度。",
    "creativeSample": "周五下午三点，老板突然说周一要开重要会议，需要我准备presentation。这意味着我的周末泡汤了。我可以抱怨，可以生气，但有什么用？我深吸一口气，开始列提纲。晚上我拒绝了朋友的聚会邀请，周六周日都在家准备资料。过程很枯燥，但我告诉自己：这是机会，不是负担。如果我做得好，也许能得到提拔。周一早上，我的presentation得到了所有人的认可，老板当场决定让我负责这个项目。<strong>同样的事情，抱怨的人只看到损失的周末，积极的人看到了机会。</strong>我选择后者，所以我得到了回报。态度决定一切。",
    "erotica": "写一个应对突发状况的激情：前任突然出现，三人之间复杂的化学反应。",
    "eroticaSample": "玄关外暴雨如注，空气中混杂着景修身上潮湿的草木味与陆锋滚烫的雄性麝香。我被陆锋从后方死死按在窗台上，冰冷的玻璃与我滚烫的乳房形成剧烈反差。\n“看清楚，他是怎么弄我的。”我回头看向站在暗影里的景修，眼神里没有羞耻，只有挑衅。陆锋发出一声低哑的粗喘，那根早已充血、布满青筋的肉棒毫无预兆地贯穿了我的阴道我能清晰感觉到那硕大的冠状沟正粗暴地刮蹭过每一道内壁褶皱，那种强烈的位移感让我脊背反弓，阴道口因为极度扩张而呈现出半透明的紧绷红润。\n景修眼底燃起近乎毁灭的欲念，他大步逼近，粗粝的长指直接捅进我正包裹着肉棒的穴腔缝隙。在极窄的空间里，他的指节与陆锋的阴茎硬生生挤在一起，疯狂按压那颗早已充血隆起的阴蒂。\n“都要……再深一点！”我支离破碎地低吼，主动分开双腿，将泥泞不堪的秘境完全向他们敞开。\n随着景修也彻底褪去束缚，两根粗壮的、带着高温的巨物在狭窄的阴道内疯狂交叠。那种近乎要把身体撕裂的胀满感，让我的内壁极度兴奋而发生痉挛式的收缩，死死锁住体内的侵略者。陆锋每一次深达子宫口的撞击，都会带起景修肉棒的剧烈摩擦。大量粘稠、温热的爱液随着三人毫无章法的冲撞，在静谧的房间里激起羞耻的“啧啧”水声。\n我成了这场官能盛宴的主宰，双手同时扣住两人的后脑，贪婪地交换着带着酒气与热度的唾液。在高潮崩塌的前一秒，我感受到两股滚烫的精液同时在阴道深处喷薄而出，将那种跨越新欢旧爱的占有欲，彻底溺死在这一场肉体合谋的洪流里。"
