    "creativeSample": "周日早上，我泡了一个很长的热水澡。不是淋浴，是浴缸，放满了水，水温比平时高一点，滴了几滴薰衣草精油，然后整个人沉进去。我在浴缸里泡了将近一个小时，什么都没想，眼睛闭着，就感受水的温度和那个气味。这一周，我和很多人说了很多话，处理了很多事，回应了很多要求。这些都是消耗，真实的，可以量化的消耗。浴缸里的这一个小时，我感觉那些消耗在慢慢填回来。出来之后，我穿上很旧很软的睡衣，在沙发上坐着，煮了杯茶，切了点水果，打开那本读了一半的书。我读了两个小时，中间一次都没看手机。下午我睡了一觉，没有设闹钟，自然醒，窗外天色已经偏黄。我在床上躺了一会儿，感受到身体里有什么东西补回来了，不是完全的，但比早上多了一些。晚上我早早关灯，在黑暗里想着明天，不是焦虑地想，是平静地想，准备好的那种。周日做的这些事，我把它们叫做准备，为了接下来那五天。",
