    "creative": "写一个老宅的超自然体验：每到深夜都有轻微震动，像楼上有人走动，但楼上是空置的。",
    "creativeSample": "凌晨两点十七分，你又醒了。\n不是因为噪音——这栋楼安静得不正常，连水管的咕噜声都没有。是因为<strong>震动</strong>，非常轻微，从床板传上来，频率规律得像脚步。\n你盯着天花板，试图用理性解释：是地铁？但最近的线路在三公里外。是楼上住户？但房东说六楼空了两年，钥匙只有物业有。\n震动停了。你松了口气，翻身准备继续睡，然后<strong>它又开始了</strong>，这次更近，像是从床头移到床尾，慢慢的，像在巡视。\n你屏住呼吸，伸手去够床头柜上的手机——指尖刚碰到屏幕，震动突然停在正上方。\n<strong>正上方。</strong>\n你的脊椎像过电一样僵直。不敢动，不敢出声，甚至不敢眨眼，因为你突然意识到：如果现在抬头，会不会看见天花板上有什么？\n手机屏幕自动熄灭了，房间陷入完全的黑暗。你数自己的心跳，一下、两下、三十下，震动终于远去，回到天花板的角落，然后彻底消失。\n你没有开灯。因为更可怕的不是看见什么，而是<strong>确认它的存在</strong>。\n第二天你在楼梯间遇到三楼的老太太，她看你的眼神很奇怪：”你昨晚没事吧？我听见你房间一直有声音。”\n但你一整晚都没下床。\n你问她听到了什么声音，她皱眉：“走来走去的脚步声，从凌晨两点多一直到四点。”顿了顿，“我以为你在锻炼。”\n你没有告诉她，你那晚从两点十七分开始，就一直躺在床上，一动不动，直到天亮。\n那天晚上你决定在客厅沙发上睡。凌晨两点十七分，震动准时开始——这次是从卧室传来的，稳定、规律，像是有什么东西在你的床上来回走动。\n你蜷缩在沙发上，盯着卧室紧闭的门，直到天亮。",
    "erotica": "写一个春日公园场景：在樱花树下的野外性爱，春天的气息催化欲望。",
    "eroticaSample": "樱花飘落如雪，她被他抵在树干上，裙子撩到腰，内裤扯到一边。他从正面进入，双手托起她臀，让她腿缠上腰。花瓣落在两人肩头，春风带着甜香催化欲望。\n他抽送得缓慢而深，每一下都顶到最深。她低声喘息，花香混着体味。她双手抱紧他脖子，臀往前迎合。他把她放下来，让她双手撑树，转身从后面进入。臀高翘，他猛撞，双手握住乳房揉捏。\n远处有散步声，她紧张地夹紧。他低声：“别怕。”刺激感让高潮来得更快。她尖叫被他捂住嘴，内壁痉挛。他低吼着射进去，热流填满她。花瓣继续飘落，两人喘息着整理衣服，春天的气息黏在皮肤上。"
