    "creativeSample": "清明节，我去给奶奶扫墓。墓碑上的照片是她年轻时的样子，笑得很温暖。我放下鲜花，擦拭墓碑上的灰尘，告诉她这一年发生的事。我换了工作，搬了家，过得还不错。我说着说着眼泪就流下来了。<strong>她去世三年了，但我还是会想起她做的饭菜，她说话的声音，她温暖的怀抱。</strong>我突然意识到，死亡不是结束，遗忘才是。只要我还记得她，她就还活在我心里。回去的路上我想，我要好好活着，不要让生命虚度。奶奶希望我快乐，我不能辜负她。这就是清明的意义吧，不仅是缅怀逝者,更是提醒生者要珍惜当下。",
