    "creative": "描写周五下班后的期待，计划着周末的美好时光。",
    "creativeSample": "周五下午四点，我就开始心不在焉了。脑子里全是周末的计划：明天睡到自然醒，去新开的咖啡馆，下午看场电影，晚上和朋友聚餐。周日可能去爬山，或者就在家里宅着看书。<strong>两天的自由时间，想想都觉得幸福。</strong>下班铃响，我飞快地收拾东西。同事问：这么急？我说：周末不等人。地铁上人很多，但我不觉得拥挤，因为我知道接下来两天我可以随心所欲。回到家我洗了个澡，换上最舒服的睡衣，点了外卖，打开一部期待已久的剧。这就是周五晚上该有的样子，放松、自由、充满期待。",
