    "creative": "描写主动选择成为什么样的人，而不是被动接受命运。",
    "creativeSample": "家里人都希望我考公务员，稳定、体面。但我不想要那样的生活。我想成为一个自由职业者，做自己喜欢的事。他们说：你会后悔的。但我说：这是我的选择。<strong>我辞掉了稳定的工作，开始做独立设计师。</strong>前半年很艰难，收入不稳定，经常熬夜。但我很快乐，因为我在做自己想做的事。一年后，我的收入超过了以前，作品也获得了认可。家人开始理解我了。我证明了：你成为什么样的人，是由你自己决定的，不是别人。命运掌握在自己手里。",
    "erotica": "写一个主动的选择：她决定探索自己的性欲，开启新的性爱旅程。",
    "eroticaSample": "我看着镜子里的自己，深吸一口气，对伴侣说：“今晚，我想主导。我想探索自己真正想要的感觉。”他眼神亮起，温柔点头：“我听你的。”\n我把他推倒在床上，跨坐在他身上，主动吻住他的唇，舌尖缠绵而主动地纠缠。我的手顺着他的胸膛下滑，握住那根已经坚硬的热度，缓缓引导它对准我早已湿润的入口。我一点点坐下去，感受着被填满的饱胀感。那一刻，我第一次真正感受到——性爱可以由我来掌控。\n我开始轻轻摇摆腰肢，每一次下沉都让自己完全吞没他。乳尖随着动作晃动，蜜汁顺着交汇处不断滑落。我低头看着他，声音带着从未有过的自信：“摸我这里……用力一点……对，就是这样……”他的手指精准地按压我的阴蒂，另一只手揉捏我的乳房。我的呼吸越来越急促，快感如潮水般涌来，却不再是被动接受，而是我主动索取。\n我加快节奏，腰肢狂野地扭动，感受着他一次次顶入最深处。快感层层叠加，我第一次主动说出自己的需求：“再深一点……我想被你顶到最里面……”高潮来临时，我全身绷紧，内壁剧烈收缩，喷出晶莹的热液，却没有停下，而是继续摇摆，直到第二次高潮来临。\n事后，我伏在他胸口，轻轻吻着他汗湿的皮肤，轻声说：“这是我第一次真正为自己而做爱……感觉好自由。”\n那一夜，我开启了属于自己的性爱旅程——不再是取悦别人，而是真正探索和享受自己的欲望。"
