    "creativeSample": "周六我什么正经事都没做。早上睡到十一点，起来吃了个brunch，然后就躺在沙发上看搞笑视频。看了三个小时，笑得肚子疼。下午我开始拼一个3000片的拼图，没有任何实用价值，纯粹是打发时间。<strong>晚上我做了一顿复杂的晚餐，光准备就花了两小时，吃却只用了十分钟。</strong>朋友问我：你今天干了什么？我说：什么都没干。但我很开心。平时工作都是为了效率、为了成果，周末就该浪费时间。做无用的事，享受无用的快乐。这才是周末的意义。",
