    "creativeSample": "那封道歉信我拖了三个月。事情不大，就是一次误会，我说了几句不该说的话，对方显然受伤了，但我一直找不到开口的契机，时间拖得越来越长，道歉反而变成了一件大事。今天早上我睡醒就拿起手机，打字，发送，没有给自己犹豫的时间。<strong>发出去的那一刻，我感觉一块石头从胸口滚开了。</strong>对方很快回复：谢谢你说这些，我早就忘了。我愣了一秒，然后笑了。我在心里放大的事，对方早就翻篇了。开始永远是最难的那一步，迈出去之后才发现，根本没有那么难。",
