    "creative": "描写一个新手第一次做某件事，笨拙但勇敢的过程。",
    "creativeSample": "我第一次去攀岩馆，完全不知道该怎么用手脚发力，抱着岩点爬了两步就滑下来了。旁边的教练看着我，没有嘲笑，只说：重心低一点，脚用力踩。我重新试，还是滑，但比第一次多爬了半米。<strong>我大概滑下来了十次，每次都比上一次爬得高一点。</strong>到最后我终于摸到了顶部的挂点，我的手抖着，心跳很快。我看了一眼下面，发现自己爬了将近四米。第一次，笨拙、狼狈，但我做到了。教练说：第一次能爬到顶的人不多。我没有说我摔了多少次，但那些摔落都是值得的。伟大从来不是起点，是终点。",
    "erotica": "写一个新手第一次的成长：她从紧张笨拙到慢慢找到自己的节奏。",
    "eroticaSample": "今晚，我决定不再只是被动接受。我躺在床上，双手微微颤抖着解开他的衬衫扣子，声音低低的：“我想……自己来试试。”他眼神温柔，点头鼓励我，却没有催促。\n我跨坐在他身上，第一次主动握住那根滚烫的热度，对准自己早已湿润却仍有些紧张的入口，缓缓往下坐。刚进去一点，我就因为那被撑开的胀满感而轻轻倒吸一口气，腰肢不由自主地僵住。他立刻伸手扶住我的腰，低声说：“慢慢来，不急，你很棒。”\n我深吸一口气，继续往下坐，一寸一寸地让他进入我体内。那种陌生的饱胀感从紧张到渐渐转为奇异的酥麻，我开始试着轻轻摇摆腰肢，却因为节奏不稳而有些笨拙地晃动。他没有笑，只是用双手温柔地托着我的臀，帮我找到平衡。\n渐渐地，我找到了感觉——每一次下沉都让自己完全吞没他，内壁自然地收缩包裹着他。我的动作从生涩变得流畅，腰肢开始有节奏地画圈，乳尖随着动作轻轻晃动，蜜汁顺着交汇处不断涌出。\n“这样……对吗？”我喘息着问。他眼神里满是赞许：“对……就是这样……你越来越会掌控节奏了。”\n我越来越自信，加快了摇摆的速度，感受着他一次次顶入最深处，G点被精准摩擦的快感如电流般窜遍全身。我主动俯身吻他，舌尖缠绵，双手按着他的胸膛，彻底主导了节奏。\n高潮来临时，我全身猛地绷紧，内壁剧烈收缩，喷出晶莹热液，却没有停下，而是继续摇摆，直到第二次高潮也如潮水般涌来。\n事后，我伏在他胸口，汗水与泪水混在一起，轻声说：“我做到了……我终于找到自己的节奏了。”\n那一夜，我从紧张笨拙的新手，第一次真正成长为懂得掌控自己欲望的女人。"
