    "creative": "描写劳动节这天，停下来想一想自己的工作究竟意味着什么。",
    "creativeSample": "劳动节放假，我难得睡到自然醒，躺着发呆。我想了想自己的工作——每天八小时，坐在电脑前，处理各种文件和邮件。有时候我会觉得这些事情没什么意义，只是为了薪水在转动。<strong>但今天我想到了一件事：我做的报告，会影响公司的决策；公司的决策，会影响一百多个人的就业。</strong>这条链条我平时从不想，但它真实存在。每一份工作都是这条链条的一环，只是我们看不见全貌。劳动节不只是休息的理由，也是重新看见劳动价值的时刻。明天回去，我想做得更认真一点。",
    "erotica": "写一个劳动节的犒劳：她决定用最放纵的方式奖励自己和伴侣这一年的辛苦。",
