    "creativeSample": "那次项目搞砸了，客户临时撤单，我们整个团队都傻眼了。老板说：重新找方向。大家都很沮丧，觉得白忙了两个月。但就在开复盘会的时候，我们发现了一件事：做这个项目过程中积累的一套数据分析方法，其实比项目本身更有价值。<strong>客户不要了，但这套方法可以卖给另一类客户。</strong>我们花了一周把它整理成可复用的工具，结果卖出去了，收回来的钱比原来那个项目还多。失败之所以值得，不是因为失败本身有意义，而是因为你在里面找到了意义。困难里真的藏着机会，就看你有没有心思去找。",
