    "creative": "描写一件看起来不可能完成的事，最后真的做完了的成就感。",
    "creativeSample": "我报了一个翻译考试，考前一个月才开始复习，那时候感觉根本不可能过。备考的一个月我几乎没有休息，每天早起背词汇，晚上做真题。有几次我坐在书桌前发呆，觉得这根本是浪费时间。<strong>但我没有放弃，只是继续做下一道题。</strong>考试那天我走进考场，发现自己没有想象中那么慌。成绩出来，我过了。我盯着屏幕看了很久，有点不相信。一个月前我说这不可能，但我还是做到了。原来不可能只是还没开始时的感觉，做着做着，它就变成了可能。",
    "erotica": "写一个突破极限的体验：她以为自己做不到，但在伴侣的耐心引导下，第一次体验到了从没感受过的高潮。",
    "eroticaSample": "我以为自己做不到。伴侣却温柔地抱住我，低声说：“相信我……我们慢慢来。”\n他把我抱到床上，先用舌头和手指温柔地侍奉我敏感的部位，直到我全身湿透。然后，他让我跨坐在他身上，缓缓进入我体内，却没有立刻抽插，而是让我自己控制节奏。\n我试探性地摇摆腰肢，他则用手指轻轻按压我的阴蒂，同时低声鼓励我：“对……就是这样……慢慢感受……你能做到的。”\n快感逐渐堆积，我开始越来越大胆地摇摆，内壁一次次收缩包裹着他。他耐心引导我尝试新的角度和深度，终于，在他的温柔鼓励下，我第一次体验到了那种从没感受过的、来自最深处的强烈高潮。\n全身像被电流击中，我哭喊着喷出大量热液，全身剧烈痉挛，却爽得几乎要昏过去。\n事后，我伏在他胸口，泪流满面，轻声说：“我以为自己做不到……谢谢你让我突破了极限。”\n那一夜，我在伴侣的耐心引导下，第一次体验到了从没感受过的高潮，也真正突破了自己的极限。"
