    "creative": "描写一段看似漫无目的的时期，后来才明白那段时间是必要的。",
    "creativeSample": "毕业后有一年，我什么计划都没有，换了三份工作，都不满意，朋友们都已经找到方向了，我还在飘。那时候我很焦虑，觉得自己是废物。但现在回头看，那一年我其实在做一件事：排除。我排除了我不适合做的，排除了我不喜欢的，每次失败都缩小了范围。<strong>那些看似浪费的时间，其实是我在找自己的过程，只是当时太近，看不清楚。</strong>不是所有的迷途都是迷失，有时候那是必要的绕路，绕过之后你才知道哪条路是你的。我现在走的这条路，是那一年帮我找到的。",
