    "creative": "描写放弃了一个旧习惯，不是靠意志力压制，而是用新的事物替代它。",
    "creativeSample": "我想戒掉睡前刷手机的习惯，试了很多次都失败了，因为我每次都在跟它对抗：不行，放下，不能看。但越对抗越想看。后来我换了策略：床头放一本书。睡前想拿手机的时候，我拿书。书不够刺激，所以我很快就困了。<strong>两周之后，我发现自己不再那么想拿手机了，因为床头那本书已经成了新的仪式。</strong>改变不是打倒旧习惯，是用新的东西把那个位置占了。现在我睡前会读二十页书，睡眠质量比以前好多了。旧习惯不是被打败的，是被挤走的。",
    "erotica": "写一个以新替旧的转变：她把旧的性爱模式放下，建立了全新的亲密方式。",
    "eroticaSample": "我跨坐在他腰间，直视着他的眼睛，手掌按在他起伏的胸肌上。今晚，我不再是那个配合他冲刺的玩偶。我倾下身，汗水顺着我的颈线滴在他的锁骨上，我闻到了彼此身上那种原始的、混杂着荷尔蒙的咸腥味。\n“别像以前那样，”我低声命令，引导着他的粗大顶端抵住我早已湿软的缝隙，“感受我，不是在使用我。”\n我缓慢地、一寸一寸地将他完全吃进体内。这种极致的撑开感让我不由自主地颤抖。没有了以往那种公式化的、为了高潮而做的剧烈撞击，取而代之的是一种充满张力的磨蹭。我的内壁紧紧裹缠着那根滚烫的肉棒，感受着它每一根凸起的青筋。\n我开始摆动腰肢，用阴蒂精准地摩擦着他的耻骨，这种主动的、诚实的索取让我感到前所未有的自由。他喉咙里发出粗重的嘶吼，双手紧紧扣住我的胯骨，那是完全合意且狂热的配合。\n“这才是我们要的，”我咬着唇，感受着体内的软肉因为过度的敏感而疯狂抽搐。随着他猛烈向上的顶端撞击到那个最深处的点，我感觉到一股滚烫的爱液顺着交合处汹涌而下。\n这不是表演，而是我身体最真实的欢呼。在那场潮红退散的余韵中，我彻底告别了旧日的剧本，在他的心跳声中，重新定义了我们要的亲密。"
