    "creative": "描写计划之外发生的某件事，反而成了这段时间最珍贵的记忆。",
    "creativeSample": "那次出差，高铁晚点了三个小时。我坐在候车室很烦躁，掏出手机刷了一会儿，然后放弃了，就发呆。旁边坐着一个老人，他看见我发呆，给了我一颗糖，说：年轻人急什么，慢慢来。我接了糖，我们就聊了起来。他是退休的地质学家，走遍了中国各地。那三个小时，他给我讲了很多故事，关于山川，关于地层，关于一个人在荒野里的感受。<strong>那次出差我忘了做什么，但那三小时我记了很久。</strong>生活就是这样，最好的部分往往在计划之外等着你。",
    "erotica": "写一个计划之外的亲密：本来只是普通的一晚，结果成了她们最难忘的一次。",
    "eroticaSample": "本来只是个再普通不过的周三。他穿着那件洗得发白的棉质T恤，我正窝在沙发边上心不在焉地踢着他的小腿。\n那一刻，空气突然粘稠。他没有预警地倾过身，粗糙的指缝穿过我颈后的碎发，带着一种近乎蛮横的磁场。这种“计划外”的欲望比任何前戏都烫人。我没有推开，反而借势直接跨坐在他结实的腿根上，指尖用力地扣进他的肩胛骨。\n没有音乐，只有衣料在急切撕扯中发出的哀鸣。当他的大手重重地掐住我的腰窝，将我整个人向下按压时，我感觉到那股滚烫、坚硬且狰狞的巨物，正隔着薄薄的布料抵在我的私密处。\n我低头咬住他的肩膀，主动扯下了最后的阻碍。当那根粗长的肉棒在毫无预设的情况下，顺着湿软的缝隙长驱直入时，那种近乎眩晕的撑开感瞬间炸裂。那是极致的扩张，阴道内壁被生硬地挤开，饱满而充实。\n他在狭促的沙发里疯狂地撞击，每一次狠力顶入都带出令人耳红心跳的噗滋声。我反手撑在沙发靠背上，腰肢随着他的律动狂乱地起伏，阴核被粗鲁地磨损着，炸开阵阵白光。我们在这场临时起意的祭典中野蛮交合，不需要温柔的试探，只有最原始的、属于两个平等灵魂的生理博弈。\n蜜汁顺着大腿根部滴落在皮革上，汗液让两具躯体变得湿滑而粘。当高潮如暴雨般降临时，我放纵自己哭喊着在他的冲刺中喷洒热液，他的低吼被我吞没在深吻里。这一晚，没有预设，却成了我们身体最刻骨铭心的勋章。"
