    "creative": "描写被生活「种」在了一个自己没有选择的地方，却在那里找到了方式绽放。（200字）",
    "creativeSample": "我没有选择要来这座城市，是工作把我带来的，那时候我对这里没有任何感情，就是一个需要在里面生活的地方，陌生，不太舒适，距离所有熟悉的东西都很远。第一年，我很难，很想回去，很难把这里当家。但人是会扎根的，不是计划好的，是日子一天一天过，把根慢慢压进土里。第二年，我发现了一条我很喜欢的街道，有一家我每周去一次的咖啡馆，认识了几个我真正喜欢的人，开始会在夜晚的某个时刻感受到一种属于这里的安静。现在我说起这座城市，说的是「我住的地方」，不再是「我被扔到的地方」。生活把我种在这里，我没有选择，但我在这里开了一点点花，那就够了。",
