    "eroticaSample": "那晚的环境完全不对：他的临时租房，很小，床很窄，楼道里有噪音，窗户没有遮光帘，月光漏进来，把房间照得有一种很生硬的感觉。我环顾了一下，差点说：要不我们算了。但我没有说，我看了看他，看见他也在看那个小而不完美的房间，然后他看向我，说：就这里了，怎么样？我说：就这里吧。我们开始，床很窄，我们不得不靠得很近，那种物理上被迫的近反而创造了一种亲密感，那个小床让我们没有办法各自待在自己的地方，必须在一起，必须调整，必须配合彼此的空间。楼道里的声音有时候会进来，月光让我们的轮廓有一种奇怪的明暗，那些不完美的元素一个一个出现，我们就接受，继续。那晚的高潮来了，在那张窄床上，在那个有楼道声音和月光的小房间里，是真实的，很好，甚至因为那些不完美而更有质感，因为我们在那些不完美里选择了继续，选择了绽放。结束之后，他说：我以为今晚会很糟。我说：我也以为。但我们没有让它糟，我们让它好了。无论生活把你种在哪里，都可以绽放，那晚我们验证了这件事。"
