    "creative": "如果能在日本住一周，你想去哪些地方？为什么？",
    "creativeSample": "如果能在日本住一周，我想先去京都住三天，每天早上只走一条路，从鸭川一直走到哲学之道，看晨雾慢慢从水面升起。接着去奈良，和鹿并排走过石板路，喂它们吃一点点鹿煎饼。最后两天留给大阪，吃章鱼烧，在道顿堀的霓虹下排队买一碗拉面。我选这些地方，是因为它们各自保存着时间的不同层次，我想慢慢走，而不是匆匆打卡。当然，一周的时间太短了，我知道自己只能走马观花。可是我还是想给自己一个机会，去试着理解每一座城市的节奏，哪怕只是懂得它们的一小部分。",
