    "eroticaSample": "雨声落在町家的瓦片上，屋里只开着一盏暖黄的灯。她倒了两杯清酒，递给我一杯，指尖碰到杯沿时停了一下。我们靠在窗边，看雨丝把街灯拉成细长的光。她说起自己一直不敢表达的心事，声音很轻，却很坚定。我没有打断，只是把她的手包在掌心里。酒慢慢喝完，她转过身，额头轻轻靠在我的肩上，我们之间的距离，一点一点消失在潮湿的夜风里。窗外的雨声渐渐变轻，屋里的灯光也显得更柔和了。我们互相看着，把这一晚的话都慢慢说完，直到夜色深得像一幅安静的画。"
