    "creative": "描述一次难忘的日本美食体验",
    "creativeSample": "那是一家藏在居酒屋后巷的小店，只有八个座位。老板是个沉默的中年人，端上来的第一道菜是刚煮好的毛豆，咸香里带着一点甜味。接着是烤鸡肉串，外皮焦脆，里面的汁水几乎要溢出来。我用日语向他道谢，他先是愣了一下，然后露出一个很浅却很真诚的笑。那一顿饭吃了将近两个小时，我的味蕾和心都被照顾得妥帖。我把那天的每一道菜都记在了笔记本上，包括它们的名字和做法的简单说明。回到家以后，我还试着照着记忆做了一次，虽然怎么也做不出那种味道。",
    "erotica": "东京酒店套房里的久别重逢",
