    "creative": "描述在日本便利店的购物经历",
    "creativeSample": "在东京的便利店，我买了一个饭团，店员用微笑说欢迎光临，结账时还会把小票双手递给我。那些看似平常的细节，让我感到一种说不清的安心。我在店门口的台阶上坐下，慢慢吃完饭团，看着路过的上班族匆匆走过。和家乡的小店相比，这里的便利店更像一个精致的服务窗口，效率很高，却从未牺牲掉对人的尊重。购物的过程，也成了一次关于礼貌的小小学习。我站在收银台前，忽然想起家乡的小卖部，老板总会多送一根棒棒糖。两种方式不同，却同样让人感到被照顾。购物这件小事，原来可以如此有温度。",
    "erotica": "民宿榻榻米上并排看星空",
    "eroticaSample": "民宿的榻榻米上铺着薄薄的被子，窗户开着，夜风带来远处的虫鸣。我们并排躺下，抬头看窗外的星空。她轻声说自己小时候很喜欢数星星，后来就忘了。我侧过身，看着她的侧脸，觉得这个夜晚很适合把心事慢慢说给对方听。她转过来，我们的呼吸近在咫尺。她的手指轻轻划过我的额发，我握住她的手，把它放在我的胸口，让她感受那份跳动。夜风吹过民宿的窗棂，发出轻轻的响声。我们在星光下静静地躺着，直到困意慢慢袭来，她的呼吸变得平稳，手还一直握着我的手。"
