    "creative": "写一篇日本旅行的反思日记",
    "creativeSample": "这次旅行结束前的最后一个晚上，我坐在酒店的窗边，把这十几天的经历在笔记本上慢慢梳理。最让我意外的，不是那些著名景点，而是某个清晨在街角遇见的老人，他一边扫落叶一边对我微笑。我开始反思自己的旅行方式，总想把每一个地方都记住，却忘了停下来和当地人说几句话。下一次，我想给自己留出更多空白，让意外有地方发生。回头看这十几天，我发现自己最大的收获，是学会了在陌生的地方慢慢地观察、慢慢地倾听。也许下一次出发，我会带着这份耐心，去更远的地方。",
