    "creative": "描写秋天的日本景色",
    "creativeSample": "我在京都的一条小路上停下来，看见一排排红叶被秋阳照得几乎透明。风一吹，叶子轻轻落下，落在我的肩膀上，又滑落到石板地面。远处传来寺庙的钟声，悠长而清澈。田地里的稻子已经变成金黄色，农舍的屋顶上晒着柿子。秋天的日本景色，是一幅不急着展开的画卷，每一笔都很克制，却让人久久舍不得移开视线。冬天到来之前，这些红叶大概就会落尽。可是我更愿意记住它们最盛的样子，那种在阳光中透亮、在风里轻轻颤动的美，它会一直留在我心里。",
