    "creative": "如果秋天有颜色，你会选哪一种，为什么",
    "creativeSample": "如果秋天有颜色，我会选一种很淡的橘黄，像是晒过太阳的旧毛衣，又像刚剥开的柿子皮在光里透出的那一层薄薄的亮。它不张扬，却有一种温热的质地，让人想起午后厨房里的蒸汽和刚出炉的红薯。秋天的颜色总有一点舍不得的意味，它在枝头慢慢变浅，在地面上慢慢铺开，像是在提醒我们，每一样美好都会退场，所以要趁它还在的时候，多看几眼。我愿意把这种橘黄留在窗台上，让它陪我把这个季节慢慢走完，也让自己学会在变化中保持温柔的注视。",
