    "creative": "写一封给去年自己的信",
    "creativeSample": "亲爱的我，你现在一定还在为那些没有完成的计划而焦虑吧。我知道你总是把自己逼得很紧，每一天都想做到最好，结果却常常在深夜里对自己叹气。我想告诉你，你其实已经走得比自己想象的远了。那些加班的夜晚、那些反复修改的文件，都是你在慢慢长大的证明。你不需要每次都完美，也不必急着证明什么。下次难过的时候，先停下来喝口热水，看看窗外的天空。你会发现，生活并没有那么糟，你也比自己以为的更有力量。那一刻我突然明白，写信的意义或许就在于，它逼着我们停下来，认认真真地去看一看自己。去年的我有许多遗憾，可那些遗憾也正是今天的我愿意重新出发的理由。",
