    "creative": "描写一次没有计划的散步",
    "creativeSample": "那天早上我出门时什么都没想，也没带手机，只是顺着巷子往前走。过了一座小桥，拐进一条没有名字的窄路，墙角长着几株开得很认真的野花。一位老奶奶坐在门口择菜，抬头冲我笑，好像早就认识我似的。我坐下来帮她剥豆子，她讲起年轻时在这条街上卖布的日子，声音慢慢的，带着一点点得意。走到巷子尽头，我才发现自己已经离家很远，可心里却出奇地平静。没有目的地，原来也可以是一种完整的旅程，一种被偶然温柔接住的旅程。这一次的旅行没有攻略，也没有安排，只是我一个人慢慢地走。我在街角停下来看一只猫，又在路边的小摊买了一块热乎乎的红豆饼。世界好像一下子变得很大，又一下子变得很近。",
