    "creative": "如果重阳节要重新设计，你会加入什么",
    "creativeSample": "如果重阳节要重新设计，我会加入一场家常的登高。不必是高山，一座小小的楼顶也好，让老人和孩子一起慢慢走上去。沿途可以互相讲讲自己的故事，爷爷讲年轻时的战友，孩子讲学校里有趣的事情。到了顶端，每个人写下一句想对家人说的话，塞进一只旧信封里，封好口，压在一盆菊花底下。明年再打开，看看那些话是否都已经成真，或者有没有被时间悄悄改写。我想，节日的意义不只是吃一块月饼，更是把彼此的心意放在一起，让平常的日子有一个可以回望的理由。",
