    "creative": "描写一次意外的雨",
    "creativeSample": "那天下午本来阳光很好，忽然就下起了雨。人们四散奔跑，躲进屋檐和店铺。我没有带伞，干脆站在路边，任雨水打在脸上。雨很凉，却让人一下子清醒过来。街角的小店门口挂着湿漉漉的布帘，老板在里面探出头，喊我进去躲一躲。我摇摇头，笑着向前走。路过的一个少年也没有带伞，却笑着把自己的书包举过头顶，朝我跑来，又突然停下，把一把折叠伞塞进我的手里，然后转身跑进了雨里。那一刻，我觉得这场雨，下得刚刚好。雨停以后，街道上的水洼映出蓝色的天空。我踩着水花慢慢地走，裤脚湿了一点，心里却异常轻松。原来有些意外，正是生活最慷慨的礼物，只看你愿不愿意接住它。",
    "erotica": "旅途中的第一次长谈",
    "eroticaSample": "长途大巴在夜里慢慢行驶，车厢里只剩我们两个人醒着。车窗外的灯光一闪而过，像流动的星星。她靠在窗边，轻声讲起小时候的事，讲她的梦想，讲她害怕的东西，讲那些一直没有对别人说过的心事。我安静地听，偶尔应一声，把外套披在她身上。她的声音越来越近，说到动情处会停一停，然后轻轻笑出来。后来她靠在我的肩膀上，头发蹭着我的脸颊，呼吸慢慢变得平稳。我们谁也没有睡，一直说到天边泛起鱼肚白，车窗外的田野一片朦胧，而我们的心，靠得越来越近。"
