    "creative": "写一个关于自行车的故事",
    "creativeSample": "那辆旧自行车停在楼下已经三年了，链条生了锈，车铃也不响了，座垫上积着一层薄灰。我某天突然想骑它出去，擦干净车座，又给轮胎打足了气。骑在路上的时候，风从耳边呼呼地掠过，街道两旁的树叶被风吹得沙沙作响。我忽然想起小时候第一次骑车，摔了一跤，膝盖擦破了皮，爸爸在后面一直扶着车后座，嘴里喊着别怕，慢慢来。那种被托住的安全感，我一直都记得。骑到河边的时候，我停下来，看着水面上的光影，觉得有些东西，其实一直都在那里等着被重新想起。",
    "erotica": "十月的最后一天的晚餐",
    "eroticaSample": "那天的晚餐很简单，窗外的风有些凉，屋里的灯却很暖。他给我倒了一杯酒，说这一个月过得很快，但有你在身边，每一天都不觉得累。我举杯碰了碰他的杯子，抬眼看他，发现他的目光比灯光还要温柔。我们慢慢吃着，话越来越少，手却越来越近。他夹了一块鱼放进我的碗里，我夸他手艺好，他有些不好意思地笑。饭后我们靠在沙发上，听着窗外的风声，觉得这样的平淡日子，原来是最让人心安的礼物。我们一边吃一边聊，话题从工作聊到童年，又从童年聊回眼前的生活。他的眼神很温柔，我们之间的沉默也变得自然而舒服，不需要任何刻意的填补。"
