    "creative": "写一个周日的早晨，窗外第一场冷风吹进屋子",
    "creativeSample": "周日的早晨，我是被一阵冷风吹醒的。窗缝里钻进来的空气带着一点潮湿的青草味，床单都变得凉凉的。我本想再赖一会儿，却还是起身去关窗。楼下的早点摊刚刚支起来，白色的水汽慢慢升上来，像是在提醒我，秋天已经走到了尾声。我裹紧毯子坐在窗前，看着对面屋顶上一只麻雀缩着脖子，觉得这种冷也有它的好处，它让人愿意待在屋里，安静地把这一周的疲惫慢慢放下来。我把毯子又往身上拉了拉，闻着屋里淡淡的木头味，忽然觉得，这个周日不需要去做什么大事，只要安静地待着，就已经足够好。",
