    "creative": "写下你最近学会的一件小事",
    "creativeSample": "最近我学会了用小火慢慢煮一锅粥。以前总觉得煮粥太费时间，总是把火开得很大，结果糊了底。这次我耐心地守在灶台前，看米粒在水里慢慢舒展，慢慢变得绵软。香气一点点升起来，弥漫在整个厨房里。它不是什么了不起的技能，却让我明白，很多好东西都需要等待，急着催它只会适得其反。这件小事，让我对生活多了一点耐心。这件事看起来很小，我却一直记在心里。它提醒我，生活里的很多变化，其实都藏在日复一日的重复和耐心之中，需要用心去体会。",
