    "creative": "写一段关于放手的日记",
    "creativeSample": "今天我把那件旧毛衣从衣柜里拿出来，又放回去，反复了好几次。它是他送我的，袖口已经有些松了，我却一直舍不得扔。可是我知道，有些东西留着，只会让人在每个冷天里想起从前。今天，我终于把它装进了袋子，准备送给需要的人。袋子合上的一刻，我的手微微发抖，但心里很平静。放手并不意味着忘记，而是把那份温暖留给过去，让自己轻装上路。我把那件毛衣叠好，轻轻地放进袋子里。系绳打结的那一刻，我发现自己比想象中平静，原来放手的第一步，可以这样安静而坚定。",
