    "creative": "写一个小镇的冬季集市",
    "creativeSample": "小镇的冬季集市在广场上热热闹闹地开了起来。摊位上摆满了手工的毛线帽、炸得金黄的糖糕，还有热气腾腾的糖炒栗子。孩子们拿着棉花糖跑来跑去，老人们坐在长椅上聊着天。我买了一杯热姜茶，捧在手里暖着。卖陶器的老师傅笑着说，这些碗都是他亲手烧的，每一只都不一样。我看着那些歪歪扭扭的碗，觉得它们正是小镇最真实的样子。冬天还很长，可是集市里的热闹让人觉得，寒冷也变得可以忍受。我把那杯姜茶喝完，手心暖暖的，心里也慢慢地亮堂起来。",
    "erotica": "一起给对方织围巾的晚上",
