    "creative": "写一个人在深夜整理衣柜，想起被遗忘的人",
    "creativeSample": "深夜，我把衣柜里的衣服一件件拿出来，准备换季。翻到最底层时，我摸到了一条旧围巾，柔软的毛线已经有些起球。它的主人早已不在身边，可是那股熟悉的洗衣粉味道却突然涌上来。我忽然想起，他总爱把围巾绕成一个大圈，说这样最暖和。我把围巾拿在手里，坐在地板上，静静地发呆。衣柜敞开着，像是打开了一扇通向过去的门。我把那条旧围巾轻轻地叠好，放回原来的地方。它依然很柔软，也依然带着那股熟悉的味道。我想，有些记忆不必急着告别，它们会在某个深夜，安静地回来。",
    "erotica": "节日后的一次补偿式约会",
