    "creative": "写一次意外得到的温暖",
    "creativeSample": "那天下班，我发现伞忘在了办公室，外面又下着雨。正犹豫时，楼下的保安叔叔走过来，手里拿着一把折叠伞，说这是他的备用伞，让我先用。我连声道谢，他摆摆手，说明天还给他就行。走进雨里，伞下的温度好像一下子暖了起来。那一刻我忽然觉得，城市虽然很大，人与人之间的善意却总能在最不经意的时候出现，像一盏悄悄亮起的灯。我把伞递还给保安叔叔时，他正要转身去巡逻，脸上带着朴实的笑容。那一刻我忽然明白，温暖从来不需要多么宏大，它常常就藏在一把伞的距离里。",
