    "creative": "写一段关于选择的内心独白",
    "creativeSample": "我站在两条路的岔口，已经站了很久。一条路通向熟悉的城市，那里有安稳的工作和家人的陪伴；另一条路通向陌生的远方，充满了未知和挑战。我一直在想，哪一种生活才是我真正想要的。也许答案并不会一下子清晰，但我知道，无论选择哪一条路，都必须对自己负责。我深吸一口气，迈出了一只脚，心里有一种说不清的坚定。那一刻，我忽然不再纠结于哪条路更好。也许每一条路都有它的风景，重要的是，无论走哪一条，我都愿意把自己的脚步踏得踏实而坚定。",
    "erotica": "冬至夜的饺子与烛光",
    "eroticaSample": "冬至的晚上，我们一起包饺子。她的手沾满了面粉，还不小心在我的脸上抹了一道白印。我笑着回击，两个人闹成一团。饺子下锅后，我们坐在桌前等它熟。烛光映着她的脸，她看着我，忽然说，今年的冬至，有你真好。我握住她的手，说，明年冬至，我们还一起包。饺子下锅的时候，热气扑在脸上，她的脸颊被蒸汽熏得红红的。她侧过头，看着我，忽然伸手替我擦掉鼻尖上的一点面粉。我们对视着笑了起来，烛光摇曳，屋子里弥漫着饺子的香气，一切都显得很安静，也很温暖。"
