    "creative": "写一个在书店里遇见作者的午后",
    "creativeSample": "那天的书店格外安静，我正在书架间翻找一本旧书，忽然听见有人轻声问，你也喜欢这本书吗？我回头，看见一位戴着眼镜的中年女人，手里抱着一本同样的书。她说，这是她十年前写的，已经很久没有人提起了。我们坐在窗边聊了一个下午，她讲起写作时的孤独，也讲起读者来信时的感动。离开时，她在扉页上签下了名字，我把书紧紧抱在怀里，觉得这个午后真是珍贵。我在书架旁站了很久，直到阳光移到了地板上。那本书的扉页上写着她的名字，我忽然觉得，文字真是一种奇妙的桥梁，让素不相识的人也能彼此相遇。",
