    "creative": "描写雪后的校园",
    "creativeSample": "雪后的校园洁白一片，操场上铺着厚厚的积雪，树枝上挂满了晶莹的雪花。教学楼的窗户透出暖黄的灯光，几个学生在雪地里打雪仗，笑声一阵阵传过来。长长的走廊里很安静，地板上留着一串串湿漉漉的脚印。我站在树下，看着雪花慢慢落在肩头，忽然想起自己学生时代的冬天，那些在雪地里奔跑的日子，仿佛就在昨天，而我们却已经长大了。我沿着雪地里的脚印慢慢走，身后留下一串属于自己的印记。雪在脚下咯吱作响，我忽然想，每一个冬天，都会在这样的校园里悄悄留下一些不会被忘记的脚步。",
    "erotica": "冬日音乐会后的街头",
