    "creative": "写一个关于毛线球的故事",
    "creativeSample": "奶奶的针线筐里总有一个旧毛线球，颜色从深红慢慢变成浅粉。小时候我总爱抢过来玩，把线拉得很长，绕得满屋子都是。奶奶从不生气，只是笑着把线一圈圈绕回来。后来她用这团线给我织了一顶帽子，戴在头上又软又暖。如今奶奶已经不太能动手织东西了，但那团毛线球还在她的筐里，像是一段慢慢织成的岁月，安静地等着被人想起。我把毛线球放回筐子里，它的颜色依然温柔，线头还带着奶奶的手温。我想，有些东西是可以一直传下去的，只要有人记得，它就永远不会被丢弃。",
