    "creative": "写一个人第一次学会滑雪的瞬间",
    "creativeSample": "第一次站在雪道上时，我的腿软得像面条。教练在一旁喊，身体往前倾，不要怕。我咬咬牙，试着把重心慢慢移动。雪板开始滑动，风迎面吹来，耳边是呼啸的声音。我摔了一跤，雪花灌进了衣领，可是我没有停下。爬起来的那一刻，我忽然看见远处的山峦在阳光下闪闪发亮，心里涌起一阵从未有过的畅快。原来有些勇气，只有在摔倒之后才会真正出现。站在雪道的顶端，我深吸了一口气，耳边是风和心跳交织的声音。那一刻，我忽然不再害怕，因为我知道，无论摔倒多少次，我都能再次站起来。",
