    "creative": "写一个人对新年的期待",
    "creativeSample": "新年快到了，我开始期待新的一年。不是因为有多大的计划，而是希望生活能慢一点，把时间花在真正重要的人和事上。我想多读几本书，多去看看身边的风景，也想学会更好地照顾自己。窗外的鞭炮声还没有响起，我已经在心里默默地许下了几个愿望。它们很小，却很真实，像一颗颗饱满的种子，等待在新的一年里慢慢发芽。我把这些小小的愿望写在便签上，贴在书桌前的墙上。每天抬头看一眼，就会想起自己为什么出发，也会更有勇气去面对接下来的每一天。",
