    "creative": "描写冬日的湖面结冰",
    "creativeSample": "冬日的湖面渐渐结了一层薄冰，阳光照在上面，闪出细碎的光。风吹过时，冰面发出轻微的咔咔声，像是在低声说话。几只水鸟站在岸边，小心地看着这片突然变硬的水面。岸边的芦苇已经枯黄，在风中轻轻摇晃。我蹲下来，看着冰下隐约可见的水草，觉得这片湖在寒冷里并没有停止生长，它只是换了一种方式，安静地等待春天。冰面下的水草依然绿着，偶尔有一两条小鱼游过，留下一串细碎的涟漪。我想，这个世界上很多美好的事情，都是在看不见的地方悄悄进行着的。",
    "erotica": "大雪天的车站告别与拥抱",
    "eroticaSample": "大雪纷飞的车站，她要登上前往远方的火车。我们站在站台的角落，谁也没有先说话。广播不断响起，人群来来往往。她忽然抱住我，把脸埋在我的围巾里。我轻轻抚着她的头发，说，到了那边要给我写信。她点头，眼眶湿湿的。火车鸣笛的那一刻，我们的手最后一次紧紧相握，然后慢慢松开。站台上的风很大，她的围巾被吹得乱飞。广播一遍遍地响起，人群在我们身边穿梭。她把脸埋进我的怀里，声音闷闷的，说，等到了那边，要记得每天给我写信。我用力地点了点头，把她抱得更紧，直到火车的鸣笛声响起。"
