    "creative": "写一个在医院陪伴家人的夜晚",
    "creativeSample": "夜里的医院走廊很长，灯光惨白，偶尔有护士的脚步声匆匆经过。父亲躺在病床上，已经睡着了，呼吸很轻。我坐在床边，握着他的手，手心有些粗糙，却很温暖。窗外的城市灯火一盏盏亮着，远处传来救护车的鸣笛声。我想起小时候，他总是背着我走很远的路，那时候他的背是那么宽厚。现在轮到我守着他，我想，这大概就是长大的意思。病房里很安静，只有监护仪的声音规律地响着。我看着父亲的脸，忽然觉得，人在脆弱的时候，最需要的就是有人在身边，握着他的手，告诉他，别怕。",
