    "creative": "写一段关于放下的回忆",
    "creativeSample": "那年夏天，我和他在河边吵了一架，谁也不肯先低头。之后的很多年，我常常在心里反复想那天的情景，想着如果当时我说了一句软话，结局是不是会不一样。直到有一天，我在整理旧物时，翻到了当年他写给我的信，字迹歪歪扭扭的，写着对不起。那一刻我忽然明白，放下并不是忘记，而是终于允许自己去原谅。我把信折好，放回盒子里，心里轻松了许多。我把那封信重新折好，放回盒子里。这一次，我的心里没有了怨怼，只剩下一种淡淡的温柔，像是终于可以坦然地面对曾经的那个自己。",
