    "creative": "写一个在圣诞集市里买礼物的人",
    "creativeSample": "圣诞集市的灯串一闪一闪，空气里飘着热红酒和烤栗子的香味。我在摊位间慢慢走，想给朋友挑一份礼物。卖手工饰品的姑娘一直笑着给我介绍，说每一件都是她亲手做的。我看中了一只小小的银色书签，上面刻着一只歪头的小鸟。我把它买下来，想象朋友打开礼盒时的表情。走出集市时，雪开始落下，我的心里满是温暖的期待。我把银色书签握在手心里，觉得它小小的，却很有分量。走出集市时，雪落在我的睫毛上，凉凉的，我却一点也不觉得冷，只想快点见到朋友。",
