    "creative": "写一次和好朋友的长谈",
    "creativeSample": "那个冬夜，我和好朋友坐在阳台上，一人裹着一条毯子，聊了整整一晚。从小时候的糗事，聊到各自的烦恼，再聊到将来的梦想。我们笑得很大声，也哭得很安静。她说，人长大以后，最怕的就是没人愿意听你说话。我握住她的手，说，那你以后要多来找我。天快亮的时候，我们都累了，却谁也不想睡，只是靠在一起，看着天边慢慢泛白。我们一直聊到天边泛白，话题从过去绕到现在，又绕回我们曾经的约定。那一刻我觉得，有一个人可以陪你说这么多话，本身就是一种幸运。",
