    "eroticaSample": "冬夜的厨房里，热汤在锅里咕嘟咕嘟地翻滚。他站在灶前，我靠在一旁看他忙碌。他尝了一口汤，回头问我咸不咸。我凑过去，抿了一口，然后踮起脚，在他的唇边轻轻吻了一下。他愣了一下，笑着把勺子放回锅里，说，那我们先吃饭吧。两个人挨在一起，安静地吃着热腾腾的晚饭。锅里的汤咕嘟咕嘟地翻滚，香气弥漫了整个厨房。他尝了一口，回过头来问我咸淡如何。我靠过去，抿了一小口，觉得刚刚好。他看着我笑，我踮起脚，在他的唇边轻轻地吻了一下，他愣了一愣，然后笑得更开心了。"
