    "creative": "写一个关于冬夜灯火的小镇",
    "creativeSample": "小镇的冬夜总是来得很早。傍晚时分，街道两旁的灯笼一盏盏亮起，暖黄的光映在积雪上，把整条街都照得柔和。店铺的门口挂着红色的春联，偶尔有行人提着菜篮子匆匆走过。河边的小桥上，几个孩子正在放烟花，火光一闪一闪地照亮了他们的笑脸。我站在桥头，看着这一片灯火，觉得这个小镇像是一个温暖的梦，让人不愿意醒来。灯笼的光很柔和，映在雪地上，像是为小镇铺上了一层温暖的地毯。我想，人们之所以喜欢冬天的夜晚，大概就是因为它让人愿意慢下来，看一看身边的光。",
