    "eroticaSample": "雪季的滑雪道上，她摔了一跤，雪花扑了满脸。我赶紧跑过去扶她，她笑着说没事。我们坐在雪地上，看着远处的山峦慢慢被夕阳染成橙红色。她握住我的手，说，以后摔倒了，你要先扶我起来。我点点头，把她的手紧紧握住，我们一起慢慢走下山坡，影子在雪地上拉得很长。滑雪道上的风很大，她摔倒的时候，雪花扑了满脸。我急忙滑过去扶她，她笑着说没事，眼睛却亮亮的。我们坐在雪地上，看着远处的山峦被夕阳染成金色。她握住我的手，说，以后你摔倒了，我也会先扶你起来。"
