    "creative": "写下冬至那天的感受",
    "creativeSample": "冬至那天，天黑得特别早。下午四五点，窗外就已经暗下来。我站在窗前，看着远处的楼宇一点点亮起灯，心里却有一种奇怪的平静。人们常说，过了冬至，白天就会一天天变长。我想，生活也是这样，再冷的日子，只要熬过了最长的那个夜，光明就会慢慢回来。我给家里打了个电话，听着母亲的声音，觉得这个冬天，因为这一通电话，变得不那么冷了。冬至的夜晚，我把灯一盏盏打开，屋子慢慢亮起来。外面的天黑得很早，可屋里的暖光让我觉得，最长的夜，其实也是最适合慢慢等待天亮的时刻。",
