    "creative": "写一个圣诞节的意外惊喜",
    "creativeSample": "圣诞节的早晨，我醒来时发现床头多了一个小盒子。打开来，里面是一条手织的围巾，颜色是我最喜欢的浅蓝。卡片上没有署名，只写着一行字：愿你在冬天也不觉得冷。我翻来覆去看了很久，猜了很多人，最后还是忍不住笑了出来。走到窗前，雪花正安静地落着，我把围巾裹在脖子上，觉得这个圣诞，是我今年收到过的最温暖的礼物。我站在街头，看着人群来来往往，每个人的脸上都带着或多或少的笑意。我忽然觉得，平安夜的意义，也许就是让人们暂时放下隔阂，彼此靠近一点。",
