    "creative": "写一个在寒冷中仍然坚持跑步的女孩",
    "creativeSample": "清晨五点，天还没亮，街道上只有路灯的光。女孩裹着厚厚的外套，戴着一顶毛线帽，一步一步地跑了起来。呼出的白气在冷空气里凝成小小的云朵。她的脚步起初有些沉重，慢慢地，身体热了起来，呼吸也变得均匀。路过早餐铺时，老板向她挥手，她笑着点头。跑完一圈，她站在路口，望着东方慢慢泛起的鱼肚白，心里有一种说不出的踏实。一年的时光，有时像一条平静的河，有时却像湍急的浪。可是回头看，它们都在我心里留下了痕迹，让我成为今天这个更加完整的自己。",
